const out=[];
for(let i=0;i<$input.all().length;i++){
 const item=$input.all()[i];
 const job=$('Download TOR Document').itemMatching(i).json;
 // HTTP Request may replace input JSON. Prefer linked upstream job when available.
 let original={};
 try{original=$('Prepare PDF Test').itemMatching(i).json;}catch(e){original=job;}
 if(!item.binary?.data){out.push({json:{...original,sourceFormat:'error',fetchError:item.json?.error?.message||'No binary data'},pairedItem:{item:i}});continue;}
 const b=await this.helpers.getBinaryDataBuffer(i,'data');
 const sig=b.subarray(0,4).toString('hex');
 const head=b.subarray(0,8192).toString('latin1').trimStart();
 const filename=String(item.binary.data.fileName||'').toLowerCase();
 const mimeType=String(item.binary.data.mimeType||'').toLowerCase();
 let fmt='unknown';
 if(['504b0304','504b0506','504b0708'].includes(sig))fmt='zip';
 else if(head.startsWith('%PDF-'))fmt='pdf';
 else if(/<!doctype\s+html|<html\b|<head\b|<body\b/i.test(head))fmt='html';
 else if(sig.startsWith('ffd8ff')||sig==='89504e47'||sig.startsWith('47494638'))fmt='image';
 else if(/\.html?$/.test(filename)||mimeType.includes('html'))fmt='html';
 else if(filename.endsWith('.pdf')||mimeType.includes('pdf'))fmt='pdf';
 else if(filename.endsWith('.zip')||mimeType.includes('zip'))fmt='zip';
 const charset=head.match(/charset\s*=\s*["']?\s*([\w-]+)/i)?.[1]||null;
 out.push({json:{...original,sourceFormat:fmt,filename,mimeType,charset,sizeBytes:b.length,signature:sig,fetchError:null},binary:item.binary,pairedItem:{item:i}});
}
return out;

