for(const it of $input.all()) {
 const d=it.json; const id=String(d.projectId||'').trim(); if(!id)continue;
 if(!m.has(id))m.set(id,{projectId:id,title:d.title||'',status:d.status||'',documentUrl:d.documentUrl||'',publishedAt:d.publishedAt||null,documents:[]});
 const p=m.get(id);
 p.documents.push({filename:d.attachmentFilename||d.filename||null,sourceFormat:d.sourceFormat||'unknown',extractionStatus:d.extractionStatus||'unknown',pages:d.pages??null,extractedText:String(d.extractedText||'')});
