const r = $input.first().json;

if (
  r.message?.content?.trim() !== 'OK' ||
  r.done_reason !== 'stop'
) {
  throw new Error(
    'Qwen not ready: ' + JSON.stringify(r)
  );
}

return $input.all();

const catalogMap = new Map();

for (const item of $input.all()) {
  const t = item.json || {};

  if (t.status !== 'active' || !t._id) continue;

  const id = String(t._id?.$oid || t._id);

  if (!/^[a-f0-9]{24}$/i.test(id)) continue;

  const text = String(t.text || '').trim();

  if (!text || !t.category || !t.type) continue;

  catalogMap.set(id, {
    id,
    text,
    contractorLabel: String(t.contractorLabel || '').trim(),
    category: t.category,
    type: t.type,
    aliases: Array.isArray(t.aliases) ? t.aliases : []
  });
}

const catalog = [...catalogMap.values()];
const totalCatalogTags = catalog.length;

const projects = $('Group Documents by Project')
  .all()
  .map(item => item.json);

const normalizeDigits = value =>
  String(value || '').replace(/[๐-๙]/g, c =>
    String(c.charCodeAt(0) - 0x0E50)
  );

const aiSystemPrompt = `
FACT EXTRACTION:
- Use only facts supported by DOCUMENT.
- Unknown values must be null; missing arrays must be [].
- Budget means project budget, not bidder financial thresholds.
- Never treat announcement dates as contract dates.
- Use YYYY-MM-DD only for explicit contract dates.
- For shared procurement plans, extract only the matching project.

EVIDENCE:
- Every evidence must be one short, continuous, verbatim
  substring of DOCUMENT, preserving exact characters.
- Never paraphrase, combine quotations or use ellipses.
- Omit any claim whose evidence cannot be found exactly.

TAGS:
- Reuse matching catalog tags using their exact tagId.
- Create new tags only for distinct, reusable concepts
  not already covered by the catalog.
- Prefer precision over quantity.
- Avoid duplicate, synonymous or overlapping tags.
- Do not create tags for quantities, prices, dates,
  brands, models or minor technical variants.
- specification = goods, services or deliverables.
- contractor_requirement = bidder qualifications
  or eligibility, such as financial capacity,
  registration, experience or required certifications.
- Do not confuse product requirements with bidder qualifications.
- Generic delivery, warranty, payment, penalty and
  evaluation conditions belong in detailed requirements.
- Incidental installation or warranty does not automatically
  establish a separate service deliverable.
- Never invent catalog IDs or unsupported qualifications.

CONTRACTOR LABELS:
- Every new tag requires text and contractorLabel.
- text describes the project concept.
- contractorLabel describes the corresponding supplier,
  provider, contractor capability or bidder qualification.
- Both labels represent one tag, not separate concepts.
- Do not invent licenses, certifications or authorizations.
- Reused tags need only the existing tagId.

DETAILED REQUIREMENTS:
- Maximum 8 independently checkable requirements.
- Preserve exact quantities, thresholds and variants.
- Prioritize important technical and bidder requirements.
- Categories: technical_specification, product_condition,
  bidder_qualification, delivery_condition, other.
- appliesTo = item name or null.
- requirementLevel = required, preferred or informational.

Return exactly the JSON structure specified below.
No markdown, explanations or extra fields.
{
  "departmentName": null,
  "procurementMethod": null,
  "budgetAmount": null,
  "projectStartAt": null,
  "projectEndAt": null,
  "aiExtractedRequirements": [
    {
      "text": "condition",
      "category": "technical_specification",
      "appliesTo": null,
      "requirementLevel": "required",
      "evidence": "exact quote"
    }
  ],
  "tagSuggestions": [
    {
      "action": "reuse",
      "tagId": "existing catalog ID",
      "requirementLevel": "required",
      "confidence": 0.9,
      "evidence": "exact quote"
    },
    {
      "action": "create",
      "text": "Broad concept",
      "contractorLabel": "Corresponding contractor capability or qualification",
      "category": "capability",
      "type": "specification",
      "requirementLevel": "required",
      "confidence": 0.9,
      "evidence": "exact quote"
    }
  ]
}

Use YYYY-MM-DD only for explicit contract dates.
Return JSON only. No markdown or explanation.
`.trim();

const output = [];

for (const p of projects) {
  const projectId = String(p.projectId || '').trim();
  if (!projectId) continue;

  const documentTexts = [];
  const documentIssues = [];

  for (const doc of p.documents || []) {
    let text = String(doc.extractedText || '').trim();
    if (!text) continue;

    // Match the correct row in shared procurement plans.
    if (/^P\d/i.test(projectId)) {
      const index = normalizeDigits(text)
        .indexOf(normalizeDigits(projectId));

      if (index < 0) {
        documentIssues.push(
          'Project ID missing in ' +
          (doc.filename || 'document')
        );
        continue;
      }

      text =
        text.slice(0, Math.min(400, text.length)) +
        '\n[PROJECT ROW]\n' +
        text.slice(
          Math.max(0, index - 100),
          index + 1200
        );
    }

    documentTexts.push(
      '### ' + (doc.filename || 'Document') +
      '\n' + text
    );
  }

  const raw = documentTexts.join('\n\n');
  if (!raw.trim()) continue;

  const sourceText = raw.length > 16000
    ? raw.slice(0, 11500) +
      '\n[DOCUMENT MIDDLE OMITTED]\n' +
      raw.slice(-3500)
    : raw;

  const aiPrompt = [
    'PROJECT ID: ' + projectId,
    'TITLE: ' + String(p.title || ''),
    'STATUS: ' + String(p.status || ''),
    '',
    'EXISTING TAGS:',
    JSON.stringify(catalog),
    '',
    'DOCUMENT:',
    sourceText
  ].join('\n');

  output.push({
    json: {
      projectId,
      title: p.title,
      status: p.status,
      documentUrl: p.documentUrl,
      aiPrompt,
      originalAiPrompt: aiPrompt,
      aiSystemPrompt,
      tagCatalog: catalog,
      totalCatalogTags,
      sourceText,
      documentIssues,
      attempt: 1,
      lastValidationErrors: [],
      model: 'qwen3.5:9bu'
    }
  });
}

return output;

// IMPORTANT: This Code node uses the approved data from its ancestor
// because the preceding MongoDB Find returns catalog documents.
const d = $('Prepare Canonical Tag Upsert').first().json;
const ai=d.validatedAi;
if(!d.reviewPassed || !d.validationPassed || !ai) throw Error('Review approval missing');
const idOf=x=>String(x?.$oid||x||'');
const normalize=x=>String(x||'').normalize('NFKC').trim().toLowerCase().replace(/\s+/g,' ');
const catalog=$input.all().map(x=>x.json).filter(x=>x._id);
const suggestions=ai.tagSuggestions||[];
const assigned=[],ids=new Set();
for(const s of suggestions){
 let tag;
 if(s.action==='reuse') tag=catalog.find(t=>idOf(t._id)===idOf(s.tagId));
 else tag=catalog.find(t=>t.category===s.category && normalize(t.text)===normalize(s.text));
 if(!tag) throw Error('Cannot resolve tag: '+(s.text||s.tagId));
 const id=idOf(tag._id);
 if(!/^[a-f0-9]{24}$/i.test(id)) throw Error('Invalid BSON tag id: '+id);
 if(ids.has(id)) throw Error('Two proposals resolve to same tag '+id);
 ids.add(id);
 assigned.push({tagId:id,requirementLevel:s.requirementLevel,evidence:s.evidence,source:'ai',confidence:Number(s.confidence),reviewStatus:'suggested'});
}
// Retain manual/crawler and previously approved or rejected assignments.
// Replace only unreviewed AI suggestions, without duplicating kept IDs.
const kept={$filter:{input:{$ifNull:['$tagAssignments',[]]},as:'a',cond:{$or:[{$ne:['$$a.source','ai']},{$in:['$$a.reviewStatus',['approved','rejected']]}]}}};
const proposed={$map:{input:{$literal:assigned},as:'a',in:{tagId:{$toObjectId:'$$a.tagId'},requirementLevel:'$$a.requirementLevel',evidence:'$$a.evidence',source:'$$a.source',confidence:'$$a.confidence',reviewStatus:'$$a.reviewStatus'}}};
const nonduplicates={$filter:{input:proposed,as:'p',cond:{$not:[{$in:[{$toString:'$$p.tagId'},{$map:{input:kept,as:'k',in:{$toString:'$$k.tagId'}}}]}]}}};
const values={
 tagAssignments:{$concatArrays:[kept,nonduplicates]},
 aiTagSuggestions:{$literal:suggestions.map(s=>({...s,source:'ai',reviewStatus:'suggested'}))},
 aiExtractedRequirements:{$literal:ai.aiExtractedRequirements||[]},
 aiProcessing:{$literal:{status:'completed',version:3,model:d.model||'qwen3.5:4b',processedAt:new Date().toISOString(),attempts:Number(d.attempt||1),tagReviewStatus:'approved',catalogSizeAtEvaluation:Number(d.totalCatalogTags||0)}}
};
for(const k of ['departmentName','procurementMethod']) if(typeof ai[k]==='string' && ai[k].trim()) values[k]={$literal:ai[k].trim()};
if(typeof ai.budgetAmount==='number' && Number.isFinite(ai.budgetAmount) && ai.budgetAmount>=0) values.budget={$mergeObjects:[{$ifNull:['$budget',{}]},{maxAmount:ai.budgetAmount}]};
for(const k of ['projectStartAt','projectEndAt']) if(typeof ai[k]==='string' && /^\d{4}-\d{2}-\d{2}$/.test(ai[k])) values[k]={$literal:ai[k]};
const pipeline=[{$match:{projectId:String(d.projectId)}},{$limit:1},{$set:values},{$merge:{into:'tor_announcements',on:'_id',whenMatched:'merge',whenNotMatched:'discard'}}];
return [{json:{projectId:String(d.projectId),resolvedTagIds:assigned.map(x=>x.tagId),torWritePipeline:JSON.stringify(pipeline),expectedTagCount:assigned.length}}];

const expected=$('Prepare BSON Tag Assignments').first().json;
const tor=$input.first()?.json;
if(!tor || tor.projectId!==expected.projectId) throw Error('TOR missing after write');
if(tor.aiProcessing?.status!=='completed'||tor.aiProcessing?.version!==3) throw Error('Processing status/version not saved');
const idOf=x=>String(x?.$oid||x||'');
const ids=(tor.tagAssignments||[]).map(a=>idOf(a.tagId));
for(const id of expected.resolvedTagIds) if(!ids.includes(id)) throw Error('Missing tag link '+id);
return [{json:{projectId:tor.projectId,success:true,aiProcessing:tor.aiProcessing,linkedTagIds:expected.resolvedTagIds,assignmentCount:(tor.tagAssignments||[]).length}}];

return $input.all().map(item => {
  const d = item.json;

  const original = String(
    d.originalAiPrompt || d.aiPrompt || ''
  ).trim();

  if (!d.projectId || !original) {
    throw new Error('projectId and aiPrompt are required');
  }

  const attempt = Number(d.attempt || 1);

  const errors = Array.isArray(d.lastValidationErrors)
    ? d.lastValidationErrors.map(String).filter(Boolean)
    : [];

  const previousAi =
    d.previousValidatedAi || d.validatedAi || null;

  const isRetry = attempt > 1 && errors.length > 0;

  const tagOnlyCorrection =
    isRetry &&
    previousAi !== null &&
    errors.every(e =>
      /tagSuggestions\[\d+\]/i.test(e)
    );

  let correction = '';

  if (isRetry) {
    correction =
      '\n\nPREVIOUS ATTEMPT FAILED.\n' +
      'FIX THESE ERRORS:\n- ' +
      errors.slice(0, 10).join('\n- ');
  }

  if (tagOnlyCorrection) {
    correction +=
      '\n\nPREVIOUS VALIDATED EXTRACTION:\n' +
      JSON.stringify(previousAi) +
      '\n\nCorrect ONLY tagSuggestions.' +
      '\nPreserve all other extraction fields exactly.' +
      '\nFollow the reviewer recommendations.' +
      '\nReturn the complete corrected JSON object.';
  } else if (isRetry) {
    correction +=
      '\n\nReturn the complete corrected JSON object.' +
      '\nUse source-supported facts and exact evidence.' +
      '\nFor reuse, select tagId only from the existing catalog.' +
      '\nNever invent tag IDs.';
  }

  return {
    json: {
      ...d,

      attempt,
      originalAiPrompt: original,
      requestPrompt: original + correction, 

      previousValidatedAi: previousAi,

      validatedAi: null,
      validationPassed: false,
      reviewPassed: false
    }
  };
});

const allowedCats = new Set([
  "technology",
  "skill",
  "certification",
  "industry",
  "project_type",
  "capability",
  "requirement",
]);
const types = new Set(["specification", "contractor_requirement"]);
const levels = new Set(["required", "preferred", "informational"]);
const reqCats = new Set([
  "technical_specification",
  "product_condition",
  "bidder_qualification",
  "delivery_condition",
  "other",
]);
const norm = (s) =>
  String(s || "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");
const out = [];
for (const item of $input.all()) {
  const d = item.json,
    errors = [];
  let ai;
  try {
    const response = d.ollamaResponse;
    if (response?.error) throw Error(JSON.stringify(response.error));
    let raw = response?.message?.content;
    if (typeof raw !== "string") throw Error("Missing message.content");
    raw = raw
      .replace(/^```(?:json)?\s*/i, "")
      .replace(/\s*```$/, "")
      .trim();
    ai = JSON.parse(raw);
    if (!ai || Array.isArray(ai) || typeof ai !== "object")
      throw Error("Expected JSON object");
  } catch (e) {
    errors.push("JSON: " + e.message);
  }
  if (ai) {
    if (!Array.isArray(ai.aiExtractedRequirements))
      errors.push("aiExtractedRequirements must be array");
    if (!Array.isArray(ai.tagSuggestions))
      errors.push("tagSuggestions must be array");
    const requirements = Array.isArray(ai.aiExtractedRequirements)
      ? ai.aiExtractedRequirements
      : [];
    const suggestions = Array.isArray(ai.tagSuggestions)
      ? ai.tagSuggestions
      : [];
    if (requirements.length > 8) errors.push("Maximum 8 detailed requirements");
    const catalog = (d.tagCatalog || []).filter(
      (t) => t && t.status !== "inactive",
    );
    const used = new Set();
    for (const [i, r] of requirements.entries()) {
      if (!r || typeof r.text !== "string" || !r.text.trim())
        errors.push(`requirement[${i}] text missing`);
      if (!reqCats.has(r?.category))
        errors.push(`requirement[${i}] invalid category`);
      if (!levels.has(r?.requirementLevel))
        errors.push(`requirement[${i}] invalid requirementLevel`);
      if (typeof r?.evidence !== "string" || !r.evidence.trim())
        errors.push(`requirement[${i}] missing evidence`);
    }
    for (const [i, t] of suggestions.entries()) {
      const k = `tagSuggestions[${i}]`;
      if (!["reuse", "create"].includes(t?.action)) {
        errors.push(k + " action must be reuse or create");
        continue;
      }
      if (!levels.has(t.requirementLevel))
        errors.push(k + " invalid requirementLevel");
      if (typeof t.evidence !== "string" || !t.evidence.trim())
        errors.push(k + " missing evidence");
      if (
        typeof t.confidence !== "number" ||
        t.confidence < 0 ||
        t.confidence > 1
      )
        errors.push(k + " confidence must be 0..1");
      if (t.action === "reuse") {
        if (t.action === "reuse") {
          const id = String(t.tagId || "").trim();

          if (!/^[a-f0-9]{24}$/i.test(id)) {
            errors.push(k + " invalid or missing tagId");
          } else {
            const matches = catalog.filter(
              (c) => String(c.id || c._id?.$oid || c._id || "") === id,
            );

            if (matches.length !== 1) {
              errors.push(k + " tagId not found in active catalog: " + id);
            } else {
              const existing = matches[0];

              // Use authoritative catalog data
              t.tagId = id;
              t.text = existing.text;

              if (t.category && t.category !== existing.category) {
                errors.push(k + " category mismatch");
              }

              if (t.type && t.type !== existing.type) {
                errors.push(k + " type mismatch");
              }

              if (used.has("id:" + id)) {
                errors.push(k + " duplicate existing tag");
              }

              used.add("id:" + id);
            }
          }
        }
      } else {
        if (typeof t.text !== "string" || !t.text.trim())
          errors.push(k + " missing canonical text");
        if (
          typeof t.contractorLabel !== "string" ||
          !t.contractorLabel.trim()
        ) {
          errors.push(k + " missing contractorLabel");
        } else {
          t.contractorLabel = t.contractorLabel.trim();
        }
        if (!allowedCats.has(t.category)) errors.push(k + " invalid category");
        if (!types.has(t.type)) errors.push(k + " invalid type");
        if (t.tagId) errors.push(k + " create must not specify tagId");
        const key = "new:" + t.category + ":" + norm(t.text);
        if (used.has(key))
          errors.push(k + " duplicate proposed canonical text");
        used.add(key);
        const match = catalog.find(
          (c) =>
            c.category === t.category &&
            c.type === t.type &&
            [
              c.text,
              c.name,
              ...(Array.isArray(c.aliases) ? c.aliases : []),
            ].some((n) => norm(n) === norm(t.text)),
        );
        if (match)
          errors.push(
            k + " duplicates " + String(match.id || match._id) + "; reuse it",
          );
      }
    }
    if (
      ai.budgetAmount != null &&
      (typeof ai.budgetAmount !== "number" || ai.budgetAmount < 0)
    )
      errors.push("budgetAmount invalid");
    for (const k of ["projectStartAt", "projectEndAt"])
      if (ai[k] != null && !/^\d{4}-\d{2}-\d{2}$/.test(String(ai[k])))
        errors.push(k + " ISO date or null");
  }
  out.push({
    json: {
      ...d,
      validatedAi: errors.length ? null : ai,
      validationPassed: errors.length === 0,
      lastValidationErrors: errors,
      ollamaResponse: undefined,
    },
  });
}
return out;

const out=[];
for(let i=0;i<$input.all().length;i++){
 const response=$input.all()[i].json;
 const d=$('Prepare Independent Tag Review').itemMatching(i).json;
 let review=null;const errors=[];
 try{
  if(response.error)throw Error(JSON.stringify(response.error));
  let raw=String(response.message?.content||'').replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim();
  review=JSON.parse(raw);
  if(!review||!['approve','revise'].includes(review.decision)||!Array.isArray(review.errors))throw Error('Invalid review schema');
  if(review.decision==='revise'&&!review.errors.length)throw Error('Revision needs specific errors');
 }catch(e){errors.push('Reviewer response: '+e.message)}
 const passed=!errors.length&&review.decision==='approve';
 out.push({json:{...d,reviewPassed:passed,reviewDecision:review?.decision||'invalid',lastValidationErrors:passed?[]:[...errors,...(review?.errors||[])],reviewPrompt:undefined}});
}
return out;

return $input.all().map(item => {
  const d = item.json;

  const errors = Array.isArray(d.lastValidationErrors)
    ? d.lastValidationErrors
    : [];

  return {
    json: {
      ...d,
      attempt: Number(d.attempt || 1) + 1,

      // Preserve reviewer recommendations
      lastValidationErrors: errors,

      // Preserve previously extracted data for correction
      previousValidatedAi: d.validatedAi || d.previousValidatedAi || null,

      // Reset validation/review state
      validatedAi: null,
      validationPassed: false,
      reviewPassed: false,

      // Clear previous model response
      ollamaResponse: undefined,
      reviewPrompt: undefined,
      requestPrompt: undefined
    }
  };
});

const items = $input.all();

const failures = items.map(item => ({
  projectId: item.json.projectId,
  tagReviewStatus: "failed",
  attempts: Number(item.json.attempt || 1),
  errors: item.json.lastValidationErrors || [],
  note: "No database write attempted"
}));

throw new Error(JSON.stringify(failures, null, 2));

const out = [];

for (let i = 0; i < $input.all().length; i++) {
  const response = $input.all()[i].json;

  // Restore original project metadata and AI prompts
  const original = $('Prepare Generator Request')
    .itemMatching(i).json;

  out.push({
    json: {
      ...original,

      // Ollama response for the validator
      ollamaResponse: response,

      // Preserve retry state
      attempt: Number(original.attempt || 1),
      lastValidationErrors: original.lastValidationErrors || [],

      // Reset previous validation results
      validatedAi: null,
      validationPassed: false,
      reviewPassed: false
    },
    pairedItem: { item: i }
  });
}

return out;

const results = [];
const normalize = x => String(x || '').normalize('NFKC').trim().toLowerCase().replace(/\s+/g, ' ');
const idOf = x => String(x?.$oid || x || '');
for (const { json: d } of $input.all()) {
  if (!d.validationPassed || !d.reviewPassed || !d.validatedAi || !d.projectId) {
    throw new Error('Expected approved AI data and projectId');
  }
  const ai = d.validatedAi;
  const catalog = d.tagCatalog || [];
  const canonical = [];
  const seen = new Set();
  for (const t of (ai.tagSuggestions || [])) {
    if (!['required','preferred','informational'].includes(t.requirementLevel) ||
        !Number.isFinite(Number(t.confidence)) || Number(t.confidence) < 0 || Number(t.confidence) > 1 ||
        !String(t.evidence || '').trim()) throw new Error('Invalid tag assignment attributes');
    if (t.action === 'reuse') {
      if (!catalog.some(c => idOf(c.id) === idOf(t.tagId))) throw new Error('Unrecognized tagId ' + t.tagId);
    } else if (t.action === 'create') {
const text = String(t.text || '').trim();
const category = String(t.category || '').trim();
const contractorLabel = typeof t.contractorLabel === 'string'
  ? t.contractorLabel.trim()
  : '';

if (
  !text ||
  !category ||
  !contractorLabel ||
  !['specification', 'contractor_requirement'].includes(t.type)
) {
  throw new Error(
    'Invalid new tag: text, category, type and contractorLabel are required'
  );
}
      const key = category + '|' + normalize(text);
      if (seen.has(key)) throw new Error('Duplicate created tag ' + text);
      seen.add(key);
canonical.push({
  text,
  contractorLabel,
  category,
  type: t.type,
  aliases: [],
  status: 'active'
});
    } else throw new Error('Unknown tag action: ' + t.action);
  }
  // Input collection 'tags' can be empty. $unionWith injects candidates
  // from the matching TOR document instead of relying on an existing tag.
  // Requires a UNIQUE compound index on {category:1,text:1} in 'tags'.
  const pipeline = [
    {$match:{_id:{$exists:false}}},
    {$unionWith:{
      coll:'tor_announcements',
      pipeline:[
        {$match:{projectId:String(d.projectId)}},
        {$limit:1},
        {$project:{items:{$literal:canonical}}},
        {$unwind:'$items'},
        {$replaceRoot:{newRoot:'$items'}}
      ]
    }},
    {$merge:{into:'tags',on:['category','text'],whenMatched:'keepExisting',whenNotMatched:'insert'}}
  ];
  results.push({json:{...d,tagUpsertPipeline:JSON.stringify(pipeline),newTagCount:canonical.length}});
}
return results;
